svg.script:
/**/
(function() {
  const svg = document.getElementById('fm1p3-svg');
  if (!svg) return;

  const stage = svg.querySelector('#fm1p3-stage');
  const tooltip = svg.querySelector('#fm1p3-tooltip');
  const ttBg = svg.querySelector('#fm1p3-tt-bg');
  const ttText = svg.querySelector('#fm1p3-tt-text');

  // Mode Switcher Handler
  function setMode(mode) {
    if (!stage) return;
    stage.setAttribute('data-mode', mode);
  }

  // Attach button listeners
  const btnQty = svg.querySelector('#fm1p3-btn-qty');
  const btnQuality = svg.querySelector('#fm1p3-btn-quality');
  const btnWeakness = svg.querySelector('#fm1p3-btn-weakness');

  if (btnQty) {
    btnQty.addEventListener('click', () => setMode('qty'));
    btnQty.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { setMode('qty'); e.preventDefault(); } });
  }
  if (btnQuality) {
    btnQuality.addEventListener('click', () => setMode('quality'));
    btnQuality.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { setMode('quality'); e.preventDefault(); } });
  }
  if (btnWeakness) {
    btnWeakness.addEventListener('click', () => setMode('weakness'));
    btnWeakness.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { setMode('weakness'); e.preventDefault(); } });
  }

  // Tooltip Mouse Follow Engine using SVG Matrix Transformation
  function showTooltip(evt, text) {
    if (!tooltip || !ttText || !ttBg) return;
    ttText.textContent = text;

    // Measure text width
    const bbox = ttText.getBBox();
    const padding = 24;
    const width = Math.max(bbox.width + padding, 140);
    ttBg.setAttribute('width', width);

    // Get SVG Coordinates
    let pt = svg.createSVGPoint();
    pt.x = evt.clientX || (evt.touches && evt.touches[0] ? evt.touches[0].clientX : 0);
    pt.y = evt.clientY || (evt.touches && evt.touches[0] ? evt.touches[0].clientY : 0);

    const ctm = svg.getScreenCTM();
    if (ctm) {
      let svgPt = pt.matrixTransform(ctm.inverse());
      let x = svgPt.x + 15;
      let y = svgPt.y - 45;

      // Boundary checks
      if (x + width > 1060) x = svgPt.x - width - 10;
      if (y < 20) y = svgPt.y + 20;

      tooltip.setAttribute('transform', `translate(${x}, ${y})`);
      tooltip.style.opacity = '1';
    }
  }

  function hideTooltip() {
    if (tooltip) tooltip.style.opacity = '0';
  }

  // Bind tooltips to shapes with data-fm1p3-tip attribute
  const tipTargets = svg.querySelectorAll('[data-fm1p3-tip]');
  tipTargets.forEach(el => {
    const text = el.getAttribute('data-fm1p3-tip');
    el.addEventListener('mousemove', (e) => showTooltip(e, text));
    el.addEventListener('mouseenter', (e) => showTooltip(e, text));
    el.addEventListener('mouseleave', hideTooltip);
    el.addEventListener('touchstart', (e) => { showTooltip(e, text); }, {passive: true});
    el.addEventListener('touchend', hideTooltip);
  });

  // Mark standalone bound state
  svg.setAttribute('data-fm1p3-bound', 'true');
})();
/**/
